INSERT INTO practice_questions(practice_set_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:1]%' ORDER BY id LIMIT 1),'All employees must finish safety training before _____ the machinery.','{"translation": "Tất cả nhân viên phải hoàn thành khóa đào tạo an toàn trước khi vận hành máy móc.", "options_vi": {"A": "vận hành (nguyên mẫu)", "B": "vận hành (V-ing)", "C": "vận hành (to V)", "D": "sự vận hành"}, "explanation": "Sau giới từ before, dùng danh từ hoặc V-ing. Ở đây cần động từ có tân ngữ the machinery, nên chọn operating. Operate và to operate không phù hợp sau giới từ; operation là danh từ và không trực tiếp nhận tân ngữ theo cách này.", "words": ["employees", "machinery"]}',1 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:1]%' ORDER BY id LIMIT 1) AND question_text='All employees must finish safety training before _____ the machinery.');
INSERT INTO practice_options(question_id,option_label,option_text,is_correct) SELECT (SELECT id FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:1]%' ORDER BY id LIMIT 1) AND question_text='All employees must finish safety training before _____ the machinery.' ORDER BY id LIMIT 1),'A','operate',FALSE WHERE NOT EXISTS(SELECT 1 FROM practice_options WHERE question_id=(SELECT id FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:1]%' ORDER BY id LIMIT 1) AND question_text='All employees must finish safety training before _____ the machinery.' ORDER BY id LIMIT 1) AND option_label='A');
INSERT INTO practice_options(question_id,option_label,option_text,is_correct) SELECT (SELECT id FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:1]%' ORDER BY id LIMIT 1) AND question_text='All employees must finish safety training before _____ the machinery.' ORDER BY id LIMIT 1),'B','operating',TRUE WHERE NOT EXISTS(SELECT 1 FROM practice_options WHERE question_id=(SELECT id FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:1]%' ORDER BY id LIMIT 1) AND question_text='All employees must finish safety training before _____ the machinery.' ORDER BY id LIMIT 1) AND option_label='B');
