INSERT INTO practice_questions(practice_set_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:5]%' ORDER BY id LIMIT 1),'The proposal, _____ financial implications were initially overlooked, was later rejected.','{"translation": "Đề xuất, mà các tác động tài chính ban đầu đã bị bỏ qua, sau đó bị bác bỏ.", "options_vi": {"A": "cái mà", "B": "người mà (tân ngữ)", "C": "có ... (sở hữu)", "D": "mà"}, "explanation": "Cần quan hệ sở hữu giữa proposal và financial implications, nên dùng whose. Whose có thể chỉ sở hữu của vật. Which không trực tiếp bổ nghĩa sở hữu cho danh từ; whom dùng cho người; that không dùng trong mệnh đề quan hệ không xác định sau dấu phẩy.", "words": ["proposal", "implications"]}',2 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:5]%' ORDER BY id LIMIT 1) AND question_text='The proposal, _____ financial implications were initially overlooked, was later rejected.');
