INSERT INTO practice_questions(practice_set_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:5]%' ORDER BY id LIMIT 1),'Were the company to expand overseas, it _____ additional legal advice.','{"translation": "Nếu công ty mở rộng ra nước ngoài, công ty sẽ cần thêm tư vấn pháp lý.", "options_vi": {"A": "sẽ cần (giả định)", "B": "đã cần trước một mốc quá khứ", "C": "sẽ đã cần", "D": "cần (hiện tại)"}, "explanation": "Were the company to expand là dạng đảo của If the company were to expand, nêu giả định loại 2. Kết quả dùng would + nguyên mẫu: would need. Các dạng thì còn lại không khớp cấu trúc điều kiện giả định này.", "words": ["company", "advice"]}',3 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:5]%' ORDER BY id LIMIT 1) AND question_text='Were the company to expand overseas, it _____ additional legal advice.');
