INSERT INTO practice_questions(practice_set_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:5]%' ORDER BY id LIMIT 1),'The revised policy is intended to _____ the risk of unauthorized access.','{"translation": "Chính sách đã sửa đổi nhằm giảm thiểu nguy cơ truy cập trái phép.", "options_vi": {"A": "giữ lại", "B": "vượt quá", "C": "tiếp tục lại", "D": "giảm thiểu"}, "explanation": "Cả bốn phương án đều là động từ nguyên mẫu, vì vậy cần xét nghĩa và kết hợp từ. Mitigate the risk nghĩa là giảm thiểu rủi ro. Retain là giữ lại, exceed là vượt quá, resume là tiếp tục lại; không phù hợp mục đích chính sách bảo mật.", "words": ["policy", "access"]}',4 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:5]%' ORDER BY id LIMIT 1) AND question_text='The revised policy is intended to _____ the risk of unauthorized access.');
