INSERT INTO practice_questions(practice_set_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:5]%' ORDER BY id LIMIT 1),'The figures in the report are _____ with the results of the independent audit.','{"translation": "Các số liệu trong báo cáo nhất quán với kết quả của cuộc kiểm toán độc lập.", "options_vi": {"A": "chu đáo", "B": "nhất quán", "C": "đáng kể", "D": "một cách nhất quán"}, "explanation": "Cụm be consistent with nghĩa là nhất quán với. Considerate chỉ sự chu đáo; considerable nghĩa là đáng kể; consistently là trạng từ, không làm bổ ngữ tính từ sau are trong cấu trúc này.", "words": ["report", "audit"]}',5 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:5]%' ORDER BY id LIMIT 1) AND question_text='The figures in the report are _____ with the results of the independent audit.');
