INSERT INTO practice_questions(practice_set_id,question_text,explanation,sort_order) SELECT (SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:5]%' ORDER BY id LIMIT 1),'_____ approval from both parties, the contract may be extended for another year.','{"translation": "Tùy thuộc vào sự chấp thuận của cả hai bên, hợp đồng có thể được gia hạn thêm một năm.", "options_vi": {"A": "bất kể", "B": "thay mặt cho", "C": "tùy thuộc vào / với điều kiện", "D": "thay vì"}, "explanation": "Subject to approval diễn tả điều kiện phải được chấp thuận trước khi gia hạn. Regardless of là bất chấp, trái với điều kiện phê duyệt; on behalf of là thay mặt; instead of là thay vì.", "words": ["approval", "contract"]}',6 WHERE NOT EXISTS(SELECT 1 FROM practice_questions WHERE practice_set_id=(SELECT id FROM practice_sets WHERE skill='READING' AND part_no=5 AND instructions LIKE '[READING_PART5_LEVEL:5]%' ORDER BY id LIMIT 1) AND question_text='_____ approval from both parties, the contract may be extended for another year.');
